}

.product-card:focus {
    outline: 2px solid var(--accent-color);
    outline-offset: 2px;
}

.product-image {
    position: relative;
    overflow: hidden;
}

.product-image .image-placeholder {
    aspect-ratio: 1;
    border-radius: 0;
}

.wishlist-btn {
    position: absolute;
    top: var(--spacing-md);
    right: var(--spacing-md);
    background-color: rgba(255, 255, 255, 0.9);
    border: none;
    width: 40px;
    height: 40px;
    border-radius: 50%;
    font-size: 1.25rem;
    cursor: pointer;
    transition: all var(--transition-base);
    display: flex;
    align-items: center;
    justify-content: center;
}

.wishlist-btn:hover {
