}

.wishlist-btn.active {
    color: var(--accent-color);
}

.product-info {
    padding: var(--spacing-lg);
    flex: 1;
    display: flex;
    flex-direction: column;
}

.product-name {
    font-size: var(--font-size-base);
    font-weight: 700;
    margin-bottom: var(--spacing-xs);
}

.product-brand {
    font-size: var(--font-size-sm);
    color: var(--neutral-600);
    margin-bottom: var(--spacing-sm);
}

.product-rating {
    display: flex;
    align-items: center;
    gap: var(--spacing-sm);
    margin-bottom: var(--spacing-sm);
    font-size: var(--font-size-sm);
}

.review-count {
    color: var(--neutral-600);
}

.product-price {
    display: flex;
    align-items: center;
    gap: var(--spacing-sm);
    margin-bottom: var(--spacing-md);
}

.price {
    font-size: var(--font-size-lg);
    font-weight: 700;
}

.original-price {
    font-size: var(--font-size-sm);
    color: var(--neutral-600);
    text-decoration: line-through;
}

.product-card .btn {
    width: 100%;
    margin-top: auto;
}

/* ===========================
   Deals Section
   =========================== */

.deals-section {
    background-color: var(--neutral-100);
    padding: var(--spacing-2xl) var(--spacing-lg);
}

.deals-grid {
    max-width: 1400px;
    margin: 0 auto;
    display: grid;
    grid-template-columns: 2fr 1fr 1fr;
    gap: var(--spacing-lg);
}

.deal-card {
    background: linear-gradient(135deg, var(--primary-color) 0%, var(--neutral-700) 100%);
    color: var(--secondary-color);
    border-radius: var(--radius-lg);
    padding: var(--spacing-lg);
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: var(--spacing-lg);
    transition: transform var(--transition-base);
}

.deal-card:hover {
    transform: translateY(-2px);
}

.deal-large {
    grid-column: span 2;
}

.deal-label {
    display: inline-block;
    background-color: var(--accent-color);
    color: var(--secondary-color);
    padding: var(--spacing-xs) var(--spacing-md);
    border-radius: var(--radius-md);
    font-size: var(--font-size-sm);
    font-weight: 600;
    margin-bottom: var(--spacing-sm);
}

.deal-content h3 {
    font-size: var(--font-size-2xl);
    margin-bottom: var(--spacing-sm);
}

.deal-content h4 {
    font-size: var(--font-size-lg);
    margin-bottom: var(--spacing-xs);
}

.deal-content p {
    margin-bottom: var(--spacing-md);
    opacity: 0.95;
}

.small-text {
    font-size: var(--font-size-sm);
}

.deal-image {
    flex-shrink: 0;
}

.deal-image .image-placeholder {
    width: 150px;
    height: 150px;
}

/* ===========================
   Editorial Section
   =========================== */

.articles-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(320px, 1fr));
    gap: var(--spacing-lg);
    list-style: none;
}

.editorial-card {
    background-color: var(--secondary-color);
    border-radius: var(--radius-lg);
    overflow: hidden;
    transition: transform var(--transition-base), box-shadow var(--transition-base);
    display: flex;
    flex-direction: column;
}

.editorial-card:hover {
    transform: translateY(-4px);
    box-shadow: var(--shadow-lg);
}

.article-image {
    position: relative;
    overflow: hidden;
}

.article-image .image-placeholder {
    aspect-ratio: 16/10;
    border-radius: 0;
}

.article-category {
    position: absolute;
    top: var(--spacing-md);
    left: var(--spacing-md);
    background-color: var(--accent-color);
    color: var(--secondary-color);
    padding: var(--spacing-xs) var(--spacing-md);
    border-radius: var(--radius-md);
    font-size: var(--font-size-sm);
    font-weight: 600;
}

.article-content {
    padding: var(--spacing-lg);
    display: flex;
    flex-direction: column;
}

.article-title {
    font-size: var(--font-size-lg);
    font-weight: 700;
    margin-bottom: var(--spacing-md);
    line-height: 1.3;
}

.article-excerpt {
    color: var(--neutral-600);
    margin-bottom: var(--spacing-md);
    flex: 1;
}

.article-meta {
    display: flex;
    gap: var(--spacing-md);
    font-size: var(--font-size-sm);
    color: var(--neutral-600);
    margin-bottom: var(--spacing-md);
}

/* ===========================
   Newsletter Section
   =========================== */

.newsletter-section {
    background: linear-gradient(135deg, var(--primary-color) 0%, var(--neutral-700) 100%);
    color: var(--secondary-color);
    padding: var(--spacing-2xl) var(--spacing-lg);
}

.newsletter-content {
    max-width: 600px;
    margin: 0 auto;
    text-align: center;
}

.newsletter-content h2 {
    font-size: var(--font-size-2xl);
    margin-bottom: var(--spacing-md);
}

.newsletter-content p {
    margin-bottom: var(--spacing-lg);
    opacity: 0.95;
}

.newsletter-form {
    display: flex;
    flex-direction: column;
    gap: var(--spacing-md);
}

.form-group {
    display: flex;
    gap: var(--spacing-sm);
}

.email-input {
    flex: 1;
    padding: var(--spacing-sm) var(--spacing-md);
    border: 2px solid var(--secondary-color);
