    min-height: 20px;
    animation: slideIn var(--transition-base);
}

@keyframes slideIn {
    from {
        opacity: 0;
        transform: translateY(-10px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

.form-message.success {
    color: var(--success-color);
}

.form-message.error {
    color: var(--warning-color);
}

