}

.footer-column h4 {
    color: var(--secondary-color);
    margin-bottom: var(--spacing-md);
    font-size: var(--font-size-base);
}

.footer-column ul {
    list-style: none;
    display: flex;
    flex-direction: column;
    gap: var(--spacing-sm);
}

.footer-column a {
    color: var(--neutral-300);
    text-decoration: none;
    transition: color var(--transition-base);
}

.footer-column a:hover {
    color: var(--accent-color);
}

.social-links {
    flex-direction: row;
    gap: var(--spacing-md);
}

.footer-bottom {
    max-width: 1400px;
    margin: 0 auto;
    display: flex;
    justify-content: space-between;
    align-items: center;
    font-size: var(--font-size-sm);
}

.footer-links {
    display: flex;
    gap: var(--spacing-lg);
}

.footer-links a {
    color: var(--neutral-300);
    text-decoration: none;
    transition: color var(--transition-base);
}

.footer-links a:hover {
    color: var(--accent-color);
}

/* ===========================
   Responsive Design
   =========================== */

@media (max-width: 1024px) {
    .header-container {
        gap: var(--spacing-lg);
    }

    .nav-menu {
        gap: var(--spacing-md);
    }

    .hero {
        grid-template-columns: 1fr;
        padding: var(--spacing-lg);
    }

    .deals-grid {
        grid-template-columns: 1fr;
    }

    .deal-large {
        grid-column: span 1;
    }

    .deal-card {
        flex-direction: column;
        text-align: center;
    }

    .deal-image {
        order: -1;
    }
}

@media (max-width: 768px) {
    .header-container {
        flex-wrap: wrap;
        gap: var(--spacing-md);
    }

    .nav-menu {
        order: 3;
        flex-basis: 100%;
        justify-content: flex-start;
        gap: var(--spacing-sm);
        overflow-x: auto;
    }

    .nav-link {
        padding: var(--spacing-xs) var(--spacing-sm);
        font-size: var(--font-size-sm);
        white-space: nowrap;
    }

    .hero-content h1 {
        font-size: var(--font-size-2xl);
    }

    .products-grid {
        grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
        gap: var(--spacing-md);
    }

    .section-header {
        flex-direction: column;
        align-items: flex-start;
        gap: var(--spacing-md);
    }

    .articles-grid {
        grid-template-columns: 1fr;
    }

    .form-group {
        flex-direction: column;
    }

    .footer-bottom {
        flex-direction: column;
        gap: var(--spacing-md);
        text-align: center;
    }

    .footer-links {
        flex-wrap: wrap;
        justify-content: center;
    }
}

@media (max-width: 480px) {
    :root {
        --font-size-3xl: 1.875rem;
        --spacing-lg: 1.5rem;
        --spacing-xl: 2rem;
    }

    .header-container {
        padding: var(--spacing-md);
    }

    .logo-text {
        display: none;
    }

    .nav-menu {
        gap: var(--spacing-xs);
    }

    .featured-products,
    .editorial-section,
    .deals-section {
        padding: var(--spacing-lg) var(--spacing-sm);
    }

    .hero {
        min-height: auto;
        gap: var(--spacing-lg);
    }

    .products-grid {
        grid-template-columns: repeat(2, 1fr);
    }

    .product-name {
        font-size: var(--font-size-sm);
    }

    .article-content {
        padding: var(--spacing-md);
    }

    .newsletter-content h2 {
        font-size: var(--font-size-xl);
    }

    .footer-content {
        grid-template-columns: 1fr;
        gap: var(--spacing-lg);
    }
}

/* ===========================
   Accessibility & Forced Colors
   =========================== */

@media (forced-colors: active) {
    .btn-primary {
        border: 2px solid ButtonText;
    }

    .btn-secondary {
        border: 2px solid ButtonText;
    }

    .product-card {
        border: 1px solid CanvasText;
    }

    .deal-card {
        border: 1px solid CanvasText;
    }

    .nav-link::after {
        background-color: ButtonText;
    }
}

@media (prefers-reduced-motion: reduce) {
    * {
        animation-duration: 1ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 1ms !important;
    }
}
