.logo {
    display: flex;
    align-items: center;
    gap: var(--spacing-sm);
    font-size: var(--font-size-xl);
    font-weight: 700;
    letter-spacing: -1px;
    text-decoration: none;
    color: var(--primary-color);
}

.logo-icon {
    font-size: 1.5rem;
}

.nav-menu {
    display: flex;
    gap: var(--spacing-lg);
    flex: 1;
    justify-content: center;
}

.nav-link {
    color: var(--neutral-900);
    text-decoration: none;
    font-size: var(--font-size-sm);
    font-weight: 500;
    padding: var(--spacing-sm) var(--spacing-md);
    position: relative;
    transition: color var(--transition-base);
}

.nav-link::after {
    content: '';
    position: absolute;
    bottom: 0;
    left: 50%;
    width: 0;
    height: 2px;
    background-color: var(--accent-color);
    transform: translateX(-50%);
    transition: width var(--transition-base);
}

.nav-link:hover::after {
    width: 100%;
}

.header-actions {
    display: flex;
    gap: var(--spacing-md);
}

.icon-button {
    background: none;
    border: none;
    font-size: 1.25rem;
    cursor: pointer;
    padding: var(--spacing-sm);
    position: relative;
    transition: transform var(--transition-base);
    color: var(--primary-color);
}

.icon-button:hover {
    transform: scale(1.1);
}

.icon-button:focus {
    outline: 2px solid var(--accent-color);
    outline-offset: 2px;
    border-radius: var(--radius-sm);
}

.cart-badge {
    position: absolute;
    top: 0;
    right: 0;
    background-color: var(--accent-color);
    color: var(--secondary-color);
    font-size: var(--font-size-sm);
    width: 24px;
    height: 24px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 600;
}

/* ===========================
   Hero Section
   =========================== */

.hero {
    display: grid;
    grid-template-columns: 1fr 1fr;
    align-items: center;
    gap: var(--spacing-2xl);
    max-width: 1400px;
    margin: 0 auto;
    padding: var(--spacing-2xl) var(--spacing-lg);
    min-height: 500px;
}

.hero-content h1 {
    font-size: var(--font-size-3xl);
    font-weight: 700;
    line-height: 1.2;
    margin-bottom: var(--spacing-md);
}

.hero-subtitle {
    font-size: var(--font-size-lg);
    color: var(--neutral-600);
    margin-bottom: var(--spacing-lg);
}

.hero-image {
    display: flex;
    align-items: center;
    justify-content: center;
}

.image-placeholder {
    width: 100%;
    aspect-ratio: 1;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 120px;
    background: linear-gradient(135deg, var(--neutral-100) 0%, var(--neutral-200) 100%);
    border-radius: var(--radius-lg);
}

/* ===========================
   Buttons
   =========================== */

.btn {
    padding: var(--spacing-sm) var(--spacing-lg);
    border: 2px solid transparent;
    border-radius: var(--radius-md);
    font-size: var(--font-size-sm);
    font-weight: 600;
    cursor: pointer;
    transition: all var(--transition-base);
    text-decoration: none;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: var(--spacing-sm);
    font-family: var(--font-family-base);
}

.btn:focus {
    outline: 2px solid var(--accent-color);
    outline-offset: 2px;
}

.btn-primary {
    background-color: var(--primary-color);
    color: var(--secondary-color);
}

.btn-primary:hover {
    background-color: var(--neutral-700);
}

.btn-secondary {
    background-color: transparent;
    color: var(--primary-color);
    border-color: var(--primary-color);
}

.btn-secondary:hover {
    background-color: var(--primary-color);
    color: var(--secondary-color);
}

.btn-light {
    background-color: var(--secondary-color);
    color: var(--primary-color);
    border-color: var(--primary-color);
}

.btn-light:hover {
    background-color: var(--neutral-100);
}

.btn-link {
    background: none;
    border: none;
    color: var(--primary-color);
    padding: 0;
}

.btn-link:hover {
    color: var(--accent-color);
}

.btn-text {
    background: none;
    border: none;
    color: var(--primary-color);
    padding: 0;
    font-weight: 600;
}

.btn-text:hover {
    color: var(--accent-color);
}

/* ===========================
   Featured Products
   =========================== */

.featured-products,
.editorial-section {
    max-width: 1400px;
    margin: 0 auto;
    padding: var(--spacing-2xl) var(--spacing-lg);
}

.section-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: var(--spacing-2xl);
}

.section-header h2 {
    font-size: var(--font-size-2xl);
    font-weight: 700;
}

.view-all {
    color: var(--primary-color);
    text-decoration: none;
    font-weight: 600;
    transition: color var(--transition-base);
}

.view-all:hover {
    color: var(--accent-color);
}

.products-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
    gap: var(--spacing-lg);
    list-style: none;
}

.product-card {
    background-color: var(--secondary-color);
    border-radius: var(--radius-lg);
    overflow: hidden;
    transition: transform var(--transition-base), box-shadow var(--transition-base);
    cursor: pointer;
    display: flex;
    flex-direction: column;
}

.product-card:hover {
    transform: translateY(-4px);
    box-shadow: var(--shadow-lg);
}

.product-card:focus {
    outline: 2px solid var(--accent-color);
    outline-offset: 2px;
}

.product-image {
    position: relative;
    overflow: hidden;
}

.product-image .image-placeholder {
    aspect-ratio: 1;
    border-radius: 0;
}

.wishlist-btn {
    position: absolute;
    top: var(--spacing-md);
    right: var(--spacing-md);
    background-color: rgba(255, 255, 255, 0.9);
    border: none;
    width: 40px;
    height: 40px;
    border-radius: 50%;
    font-size: 1.25rem;
    cursor: pointer;
    transition: all var(--transition-base);
    display: flex;
    align-items: center;
    justify-content: center;
}

.wishlist-btn:hover {
    background-color: var(--secondary-color);
    transform: scale(1.1);
}

.wishlist-btn.active {
    color: var(--accent-color);
}

.product-info {
    padding: var(--spacing-lg);
    flex: 1;
    display: flex;
    flex-direction: column;
}

.product-name {
    font-size: var(--font-size-base);
    font-weight: 700;
    margin-bottom: var(--spacing-xs);
}

.product-brand {
    font-size: var(--font-size-sm);
    color: var(--neutral-600);
    margin-bottom: var(--spacing-sm);
}

.product-rating {
    display: flex;
    align-items: center;
    gap: var(--spacing-sm);
    margin-bottom: var(--spacing-sm);
    font-size: var(--font-size-sm);
}

.review-count {
    color: var(--neutral-600);
}

.product-price {
    display: flex;
    align-items: center;
    gap: var(--spacing-sm);
    margin-bottom: var(--spacing-md);
}

.price {
    font-size: var(--font-size-lg);
    font-weight: 700;
}

.original-price {
    font-size: var(--font-size-sm);
    color: var(--neutral-600);
    text-decoration: line-through;
}

.product-card .btn {
    width: 100%;
    margin-top: auto;
}

/* ===========================
   Deals Section
   =========================== */

.deals-section {
    background-color: var(--neutral-100);
    padding: var(--spacing-2xl) var(--spacing-lg);
}

.deals-grid {
    max-width: 1400px;
    margin: 0 auto;
    display: grid;
    grid-template-columns: 2fr 1fr 1fr;
    gap: var(--spacing-lg);
}

.deal-card {
    background: linear-gradient(135deg, var(--primary-color) 0%, var(--neutral-700) 100%);
    color: var(--secondary-color);
    border-radius: var(--radius-lg);
    padding: var(--spacing-lg);
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: var(--spacing-lg);
    transition: transform var(--transition-base);
}

.deal-card:hover {
    transform: translateY(-2px);
}

.deal-large {
    grid-column: span 2;
}

.deal-label {
    display: inline-block;
    background-color: var(--accent-color);
    color: var(--secondary-color);
    padding: var(--spacing-xs) var(--spacing-md);
    border-radius: var(--radius-md);
    font-size: var(--font-size-sm);
    font-weight: 600;
    margin-bottom: var(--spacing-sm);
}

.deal-content h3 {
    font-size: var(--font-size-2xl);
    margin-bottom: var(--spacing-sm);
}

.deal-content h4 {
    font-size: var(--font-size-lg);
    margin-bottom: var(--spacing-xs);
}

.deal-content p {
    margin-bottom: var(--spacing-md);
    opacity: 0.95;
}

.small-text {
    font-size: var(--font-size-sm);
}

.deal-image {
    flex-shrink: 0;
}

.deal-image .image-placeholder {
    width: 150px;
    height: 150px;
}

/* ===========================
   Editorial Section
   =========================== */

.articles-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(320px, 1fr));
    gap: var(--spacing-lg);
    list-style: none;
}

.editorial-card {
    background-color: var(--secondary-color);
    border-radius: var(--radius-lg);
    overflow: hidden;
    transition: transform var(--transition-base), box-shadow var(--transition-base);
    display: flex;
    flex-direction: column;
}

.editorial-card:hover {
    transform: translateY(-4px);
    box-shadow: var(--shadow-lg);
}

.article-image {
    position: relative;
    overflow: hidden;
}

.article-image .image-placeholder {
    aspect-ratio: 16/10;
    border-radius: 0;
}

.article-category {
    position: absolute;
    top: var(--spacing-md);
    left: var(--spacing-md);
    background-color: var(--accent-color);
    color: var(--secondary-color);
    padding: var(--spacing-xs) var(--spacing-md);
    border-radius: var(--radius-md);
    font-size: var(--font-size-sm);
    font-weight: 600;
}

.article-content {
    padding: var(--spacing-lg);
    display: flex;
    flex-direction: column;
}

.article-title {
    font-size: var(--font-size-lg);
    font-weight: 700;
    margin-bottom: var(--spacing-md);
    line-height: 1.3;
}

.article-excerpt {
    color: var(--neutral-600);
    margin-bottom: var(--spacing-md);
    flex: 1;
}

.article-meta {
    display: flex;
    gap: var(--spacing-md);
    font-size: var(--font-size-sm);
    color: var(--neutral-600);
    margin-bottom: var(--spacing-md);
}

/* ===========================
   Newsletter Section
   =========================== */

.newsletter-section {
    background: linear-gradient(135deg, var(--primary-color) 0%, var(--neutral-700) 100%);
    color: var(--secondary-color);
    padding: var(--spacing-2xl) var(--spacing-lg);
}

.newsletter-content {
    max-width: 600px;
    margin: 0 auto;
    text-align: center;
}

.newsletter-content h2 {
    font-size: var(--font-size-2xl);
    margin-bottom: var(--spacing-md);
}

.newsletter-content p {
    margin-bottom: var(--spacing-lg);
    opacity: 0.95;
}

.newsletter-form {
    display: flex;
    flex-direction: column;
    gap: var(--spacing-md);
}

.form-group {
    display: flex;
    gap: var(--spacing-sm);
}

.email-input {
    flex: 1;
    padding: var(--spacing-sm) var(--spacing-md);
    border: 2px solid var(--secondary-color);
    border-radius: var(--radius-md);
    font-size: var(--font-size-base);
    font-family: var(--font-family-base);
    background-color: var(--secondary-color);
    color: var(--primary-color);
}

.email-input:focus {
    outline: none;
    border-color: var(--accent-color);
}

.email-input::placeholder {
    color: var(--neutral-600);
}

.form-message {
    font-size: var(--font-size-sm);
    min-height: 20px;
    animation: slideIn var(--transition-base);
}

@keyframes slideIn {
    from {
        opacity: 0;
        transform: translateY(-10px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

.form-message.success {
    color: var(--success-color);
}

.form-message.error {
    color: var(--warning-color);
}

/* ===========================
   Footer
   =========================== */

.footer {
    background-color: var(--neutral-900);
    color: var(--neutral-300);
    padding: var(--spacing-2xl) var(--spacing-lg) var(--spacing-lg);
}

.footer-content {
    max-width: 1400px;
    margin: 0 auto;
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: var(--spacing-2xl);
    margin-bottom: var(--spacing-2xl);
    padding-bottom: var(--spacing-2xl);
    border-bottom: 1px solid var(--neutral-700);
}

.footer-column h4 {
    color: var(--secondary-color);
    margin-bottom: var(--spacing-md);
    font-size: var(--font-size-base);
}

.footer-column ul {
    list-style: none;
    display: flex;
    flex-direction: column;
    gap: var(--spacing-sm);
}

.footer-column a {
    color: var(--neutral-300);
    text-decoration: none;
    transition: color var(--transition-base);
}

.footer-column a:hover {
    color: var(--accent-color);
}

.social-links {
    flex-direction: row;
    gap: var(--spacing-md);
}

.footer-bottom {
    max-width: 1400px;
    margin: 0 auto;
    display: flex;
    justify-content: space-between;
    align-items: center;
    font-size: var(--font-size-sm);
}

.footer-links {
    display: flex;
    gap: var(--spacing-lg);
}

.footer-links a {
    color: var(--neutral-300);
    text-decoration: none;
    transition: color var(--transition-base);
}

.footer-links a:hover {
    color: var(--accent-color);
}

/* ===========================
   Responsive Design
   =========================== */

@media (max-width: 1024px) {
    .header-container {
        gap: var(--spacing-lg);
    }

    .nav-menu {
        gap: var(--spacing-md);
    }

    .hero {
        grid-template-columns: 1fr;
        padding: var(--spacing-lg);
    }

    .deals-grid {
        grid-template-columns: 1fr;
    }

    .deal-large {
        grid-column: span 1;
    }

    .deal-card {
        flex-direction: column;
        text-align: center;
    }

    .deal-image {
        order: -1;
    }
}

@media (max-width: 768px) {
    .header-container {
        flex-wrap: wrap;
        gap: var(--spacing-md);
    }

    .nav-menu {
        order: 3;
        flex-basis: 100%;
        justify-content: flex-start;
        gap: var(--spacing-sm);
        overflow-x: auto;
    }

    .nav-link {
        padding: var(--spacing-xs) var(--spacing-sm);
        font-size: var(--font-size-sm);
        white-space: nowrap;
    }

    .hero-content h1 {
        font-size: var(--font-size-2xl);
    }

    .products-grid {
        grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
        gap: var(--spacing-md);
    }

    .section-header {
        flex-direction: column;
        align-items: flex-start;
        gap: var(--spacing-md);
    }

    .articles-grid {
        grid-template-columns: 1fr;
    }

    .form-group {
        flex-direction: column;
    }

    .footer-bottom {
        flex-direction: column;
        gap: var(--spacing-md);
        text-align: center;
    }

    .footer-links {
        flex-wrap: wrap;
        justify-content: center;
    }
}

@media (max-width: 480px) {
    :root {
        --font-size-3xl: 1.875rem;
        --spacing-lg: 1.5rem;
        --spacing-xl: 2rem;
    }

    .header-container {
        padding: var(--spacing-md);
    }

    .logo-text {
        display: none;
    }

    .nav-menu {
        gap: var(--spacing-xs);
    }

    .featured-products,
    .editorial-section,
    .deals-section {
        padding: var(--spacing-lg) var(--spacing-sm);
    }

    .hero {
        min-height: auto;
        gap: var(--spacing-lg);
    }

    .products-grid {
        grid-template-columns: repeat(2, 1fr);
    }

    .product-name {
        font-size: var(--font-size-sm);
    }

    .article-content {
        padding: var(--spacing-md);
    }

    .newsletter-content h2 {
        font-size: var(--font-size-xl);
    }

    .footer-content {
        grid-template-columns: 1fr;
        gap: var(--spacing-lg);
    }
}

/* ===========================
   Accessibility & Forced Colors
   =========================== */

@media (forced-colors: active) {
    .btn-primary {
        border: 2px solid ButtonText;
    }

    .btn-secondary {
        border: 2px solid ButtonText;
    }

    .product-card {
        border: 1px solid CanvasText;
    }

    .deal-card {
        border: 1px solid CanvasText;
    }

    .nav-link::after {
        background-color: ButtonText;
    }
}

@media (prefers-reduced-motion: reduce) {
    * {
        animation-duration: 1ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 1ms !important;
    }
}
