// ============================================
// Component: Smooth Scroll Manager
// ============================================

class SmoothScrollManager {
    constructor() {
        this.init();
    }

    init() {
        document.querySelectorAll('a[href^="#"]').forEach((anchor) => {
            anchor.addEventListener('click', (e) => {
                const href = anchor.getAttribute('href');
                if (href === '#') return;

                e.preventDefault();
                const target = document.querySelector(href);
                if (target) {
                    target.scrollIntoView({ behavior: 'smooth' });
                }
            });
        });
    }
}

// ============================================
// Component: Intersection Observer - Lazy Loading
// ============================================

class LazyLoadManager {
    constructor() {
        this.init();
    }

    init() {
        const observer = new IntersectionObserver((entries) => {
            entries.forEach((entry) => {
                if (entry.isIntersecting) {
                    this.animateElement(entry.target);
                    observer.unobserve(entry.target);
                }
            });
        }, { threshold: 0.1 });

        // Observe product cards and editorial cards
        document.querySelectorAll('.product-card, .editorial-card, .deal-card').forEach((el) => {
            observer.observe(el);
        });
    }

    animateElement(element) {
        element.style.animation = 'fadeIn 500ms ease-out forwards';
    }
}

// ============================================
// Global Styles for Animations
// ============================================

function injectAnimationStyles() {
    const style = document.createElement('style');
    style.textContent = `
        @keyframes fadeIn {
            from {
                opacity: 0;
                transform: translateY(10px);
            }
            to {
                opacity: 1;
                transform: translateY(0);
            }
        }

        @keyframes slideInUp {
            from {
